<?php
/** TEMP PS S1613 run e9d — D: deploy darbalaukis v3.14 (4 b64 dalys, md5 + token, gyvo failo sargas v3.13.2); T (naujas procesas): V13 — #35421 (prins išsiuntė, laukia AV) be Klausimo → Surinkti AV; #35418 (ZB užsakyta 09-02, neišsiųsta) „ZB vėluoja — …“ + Paruošta siųsti; „ZB išsiuntė“ → Klausimas dingsta pats; skydelis ajax kaip testuotojas; gaudyklė prior. 4; Playwright Klausimai / Surinkti AV / Paruošta siųsti */
add_action('init', function(){
  if (!isset($_GET['ps_e9d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e9d'])); $o=array('v'=>'S1613 e9d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c4='';
    $p1=@file_get_contents($bk.'/dl-v314.part1'); $p2=@file_get_contents($bk.'/dl-v314.part2'); $p3=@file_get_contents($bk.'/dl-v314.part3'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen((string)$p3),strlen($c4));
    $code=base64_decode($p1.$p2.$p3.$c4,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='005facb497c4bd7a0b6512c3b6af426f') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='0bc7795f845d9da241efc90a6c9d891b') { $o['STOP']='gyvas ne v3.13.2 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3132-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v314.part1'); @unlink($bk.'/dl-v314.part2'); @unlink($bk.'/dl-v314.part3');
  }
  if($f==='T'||$f==='Z'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['dev_zurnalas_pries']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    update_option('ps_e9_mail',array(),false);
    add_filter('pre_wp_mail',function($r,$a){ $m=get_option('ps_e9_mail',array()); $m[]=array('to'=>is_array($a['to'])?implode(',',$a['to']):$a['to'],'s'=>$a['subject'],'b'=>mb_substr(preg_replace('/\s+/',' ',wp_strip_all_tags((string)$a['message'])),0,300)); update_option('ps_e9_mail',$m,false); return true; },4,2);
    $o['now']=current_time('mysql');
    // testuotojas sesija + nonce (e8d šablonas)
    $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
    $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok); $_COOKIE[LOGGED_IN_COOKIE]=$li; wp_set_current_user($uid);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$li)));
    $n=wp_create_nonce('ps_dl_zurnalas');
    $sk=function($id) use ($cs,$n){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $b=is_wp_error($r)?'':wp_remote_retrieve_body($r); $j=json_decode($b,true); $d=$j['data']??array(); return array('code'=>wp_remote_retrieve_response_code($r),'kl'=>$d['klausimas']??null,'kur'=>$d['kur']??null,'btn'=>$d['btn']['t']??null,'laukti'=>$d['laukti']??null,'st'=>$d['st']??null); };
    $bk=function($id){ $x=wc_get_order($id); return array('st'=>$x->get_status(),'sla'=>(string)$x->get_meta('_ps_sla_velavimas'),'sent_src'=>(string)$x->get_meta('_ps_dropship_sent_src'),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'reg'=>array_map(function($s){ return $s['sandelis'].':'.implode('/',$s['numeriai']); },Petshop_Siuntos::sarasas($id))); };
    foreach(array(35421,35418) as $id){ $o['pries'][$id]=$bk($id); $o['sk_pries'][$id]=$sk($id); }
    // Z (atskiras run'as, po T ekrano nuotraukų): ZB išsiuntė (#35418, registre V…037) → Klausimas dingsta pats
    if($f==='Z'){ $x=wc_get_order(35418); if($x->get_status()==='processing'){ $o['zb_issiusta']=Petshop_Darbalaukis::issiusta($x,null,true,'zb','web'); $o['po_35418']=$bk(35418); $o['sk_po_35418']=$sk(35418); } }
    $o['laiskai']=array_map(function($m){ return $m['to'].' | '.$m['s'].' | '.$m['b']; },get_option('ps_e9_mail',array())); delete_option('ps_e9_mail'); $o['dev_zurnalas_po']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    wp_set_current_user(0);
    $o['cookies']=array(); foreach($cs as $c){ $o['cookies'][]=array('name'=>$c->name,'value'=>$c->value); }
    $ev="({eiles:[...document.querySelectorAll('.dl-eiles a, .dl-eiles button, nav a')].map(x=>x.innerText.replace(/\\s+/g,' ')).filter(t=>/Klausimai|Surinkti AV|Paruošta/.test(t)).slice(0,6),korteles:[...document.querySelectorAll('.dl-kortele')].map(x=>x.innerText.replace(/\\s+/g,' ').slice(0,200)),nr:[...document.querySelectorAll('tr.eil .nr')].map(x=>x.innerText).slice(0,40)})";
    $o['shots']=array(
      array('n'=>'s1613_e9_klausimai'.($f==='Z'?'_po':''),'u'=>admin_url('admin.php?page=ps-desk&eile=klausimai'),'w'=>1400,'full'=>true,'eval'=>$ev),
      array('n'=>'s1613_e9_surinkti'.($f==='Z'?'_po':''),'u'=>admin_url('admin.php?page=ps-desk&eile=surinkti'),'w'=>1400,'full'=>true,'eval'=>$ev),
      array('n'=>'s1613_e9_paruosta'.($f==='Z'?'_po':''),'u'=>admin_url('admin.php?page=ps-desk&eile=paruosta'),'w'=>1400,'full'=>true,'eval'=>$ev)
    );
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
},99);
